def nombres_primes_inf_n(n):
    def est_premier(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return [num for num in range(2, n) if est_premier(num)]
